using System.Text;
using Resources;
using TplCore.Element;

namespace Fanex.Age.UI.Components.ShowHideColumn
{
    /// <summary>
    /// Renders context menu for show/hide columns
    /// </summary>
    public class ContextMenuColumns : IComponent
    {
        public const string CookiePrefix = "cookiePrefix";
        public const string ContextRegionIds = "containerId";
        public const string ContextContainerId = "parentId";
        public const string TableId = "tableId";

        ContextMenuColumns_Control_Template tpl = new ContextMenuColumns_Control_Template();

        public string RenderCheckbox(string[] texts, string[] cols, string[] colspan = null, bool showLcs = false)
        {
            var columns = string.Empty;

            tpl.checkbox.Clear();

            ContextMenuColumns_Control_checkbox_Block checkbox = new ContextMenuColumns_Control_checkbox_Block();

            var css = new StringBuilder();
            css.Append("<style>");

            for (int i = 0; i < texts.Length; i++)
            {
                checkbox.text = texts[i];
                checkbox.colName = cols[i];

                if (colspan != null)
                {
                    checkbox.colId = cols[i];
                    checkbox.colspan = colspan[i];
                }
                else
                {
                    checkbox.colId = string.Empty;
                    checkbox.colspan = string.Empty;
                }

                checkbox.showLcs = showLcs.ToString().ToLower();

                tpl.checkbox.Append(checkbox);

                columns += cols[i] + ",";

                css.Append(".");
                css.Append(cols[i]);
                css.Append(" { display: none; } ");

                css.Append("table.show");
                css.Append(cols[i]);
                css.Append(" .");
                css.Append(cols[i]);
                css.Append(" { display: table-cell; *display: block; } ");
            }

            css.Append("</style>");

            tpl.columns = columns == string.Empty ? columns : columns.Remove(columns.Length - 1, 1);
            tpl.PopupMsg = Lang.showhidecolumnAd;
            tpl.DoNotShowAgain = Lang.donotshowagain;

            return css + tpl;
        }

        public static implicit operator string(ContextMenuColumns value)
        {
            return value.ToString();
        }

        public void HideLinkedResources()
        {
            tpl.ExternalResources = null;
        }

        public override string ToString()
        {
            return tpl.ToString();
        }
    }
}